const m = (id: number, timeZone: string, weekdays: number[], start: string, end: string): Mentor =>
  ({ id, name: '', email: '', bio: '', subjects: [], timeZone, hours: weekdays.map((weekday) => ({ weekday, start, end })) });
const iso = (ds: Date[]) => ds.map((d) => d.toISOString());
const day = (a: string, b: string) => [new Date(a), new Date(b)] as const;

// london spring-forward sun 29 mar 2026: 01:00 gmt -> 02:00 bst. window 01:00-04:00 local; 01:00 missing -> 02:00 bst = 01:00z; 04:00 bst = 03:00z
assert.deepEqual(iso(classStarts(m(1, 'Europe/London', [0], '01:00', '04:00'), ...day('2026-03-29T00:00:00Z', '2026-03-30T00:00:00Z'))),
  ['2026-03-29T01:00:00.000Z', '2026-03-29T02:00:00.000Z']);
// london fall-back sun 25 oct 2026: 01:00-03:00 local; 01:00 first pass = 00:00z (bst); 03:00 gmt = 03:00z
assert.deepEqual(iso(classStarts(m(1, 'Europe/London', [0], '01:00', '03:00'), ...day('2026-10-25T00:00:00Z', '2026-10-26T00:00:00Z'))),
  ['2026-10-25T00:00:00.000Z', '2026-10-25T01:00:00.000Z', '2026-10-25T02:00:00.000Z']);
// worksAt for the second pass of 01:00 london (01:00z = 01:00 gmt) inside 01:00-03:00
assert.equal(worksAt(m(1, 'Europe/London', [0], '01:00', '03:00'), new Date('2026-10-25T01:00:00Z')), true);
// kolkata 20:00 is 14:30z -> first class 15:00z; 23:30 = 18:00z -> last start 17:00z
assert.deepEqual(iso(classStarts(m(1, 'Asia/Kolkata', [2], '20:00', '23:30'), ...day('2026-10-27T00:00:00Z', '2026-10-28T00:00:00Z'))),
  ['2026-10-27T15:00:00.000Z', '2026-10-27T16:00:00.000Z', '2026-10-27T17:00:00.000Z']);
// worksAt rejects the 14:30z wall-time start? it is not a class start; worksAt allows it (on-the-hour is isBookableTime's job)
assert.equal(worksAt(m(1, 'Asia/Kolkata', [2], '20:00', '23:30'), new Date('2026-10-27T14:30:00Z')), true);
// class ending exactly at close is kept; one minute short is dropped
assert.deepEqual(iso(classStarts(m(1, 'UTC', [2], '15:00', '16:00'), ...day('2026-10-27T00:00:00Z', '2026-10-28T00:00:00Z'))), ['2026-10-27T15:00:00.000Z']);
assert.deepEqual(iso(classStarts(m(1, 'UTC', [2], '15:00', '15:59'), ...day('2026-10-27T00:00:00Z', '2026-10-28T00:00:00Z'))), []);
// from/to inclusive at both ends
assert.deepEqual(iso(classStarts(m(1, 'UTC', [2], '10:00', '13:00'), ...day('2026-10-27T10:00:00Z', '2026-10-27T11:00:00Z'))),
  ['2026-10-27T10:00:00.000Z', '2026-10-27T11:00:00.000Z']);
// now off the hour: 12:30 -> first slot 15:00 (14:30 + ceil), last slot <= now+14d = 3 nov 12:30 -> 12:00
const now = new Date('2026-10-20T12:30:00Z');
const all = buildSlots([m(1, 'UTC', [0, 1, 2, 3, 4, 5, 6], '00:00', '23:59')], [], now);
assert.equal(all[0]!.startsAt.toISOString(), '2026-10-20T15:00:00.000Z');
assert.equal(all.at(-1)!.startsAt.toISOString(), '2026-11-03T12:00:00.000Z');
assert.equal(isBookableTime(new Date('2026-11-03T12:00:00Z'), new Date('2026-10-20T12:00:00Z')), true);
assert.equal(isBookableTime(new Date('invalid'), now), false);
// overlapping rows + several mentors: one entry per instant, strictly increasing
const many = buildSlots([m(1, 'Asia/Kolkata', [1, 2, 3], '18:30', '23:30'), m(2, 'Asia/Kolkata', [1, 2, 3], '20:30', '23:30'),
  { ...m(3, 'Asia/Kolkata', [2], '19:30', '22:30'), hours: [{ weekday: 2, start: '19:30', end: '22:30' }, { weekday: 2, start: '20:30', end: '23:30' }] }], [], now);
for (let i = 1; i < many.length; i++) assert.ok(many[i]!.startsAt.getTime() > many[i - 1]!.startsAt.getTime());
// timing at the real size: 10 mentors, ~400 bookings
const tz = ['Asia/Kolkata'];
const mentors = Array.from({ length: 10 }, (_, i) => m(i + 1, tz[0]!, [0, 1, 2, 3, 4, 5, 6], '06:30', '23:30'));
const bookings = mentors.flatMap((x) => buildSlots([x], [], now).slice(0, 40).map((s) => ({ mentorId: x.id, startsAt: s.startsAt, mentorLocalDate: '2026-10-21' })));
const t0 = performance.now(); for (let i = 0; i < 20; i++) buildSlots(mentors, bookings, now); const ms = (performance.now() - t0) / 20;
console.log(`ok tz=${process.env.TZ} buildSlots 10x14d (${bookings.length} bookings): ${ms.toFixed(2)} ms/call`);
EOF
